        teacher: '교실에 걸린 작품 하나를 정해 짝에게 다섯 문장을 낱말 하나씩만 먼저 말하게 한다. "첫인상 낱말, 본 것 낱말, 느낌 낱말, 까닭 낱말, 마무리 낱말 순서예요." 낱말이 막히는 칸은 건너뛰고 듣는 짝이 질문으로 도와준다. 완성한 뼈대는 활동지 첫 칸에 쓴다.',
        task: '작품 하나를 정해 다섯 칸에 낱말을 하나씩 말하고, 짝이 비어 있는 칸을 질문으로 도와요.',
