    wrap: '"다섯 문장 가운데 어떤 문장 쓰기가 가장 쉬웠나요? 가장 어려운 문장은요?" 몇 명에게 말하게 한다. 어려운 문장으로 "까닭"을 뽑은 학생이 많으면 다음 차시 처음에 까닭 찾기 연습을 한 번 더 한다. 출구 1번에서 느낌 문장을 본 것에 넣은 학생에게는 "눈으로 보이는가, 마음으로 느끼는가"를 다시 묻는다.',
